  'Realtime samenwerken starten': 'Mulai kolaborasi waktu nyata',
  'Stel eerst een Matrix-account in bij Instellingen → Samenwerken.':
      'Siapkan akun Matrix terlebih dahulu di Pengaturan → Kolaborasi.',
