  'De nieuwste uitgave opzoeken…': 'Mencari rilis terbaru…',
  'Dit is een grote download: ruim 500 MB binnenhalen, tijdelijk zo\'n 1,5 GB schijfruimte, en afhankelijk van je verbinding en apparaat al gauw tien tot dertig minuten werk. Daarna blijft er een index van enkele honderden megabytes staan. Op een verbinding die per megabyte betaalt, doe je dit liever niet.':
      'Ini unduhan besar: lebih dari 500 MB yang harus diambil, sekitar 1,5 GB ruang disk untuk sementara, dan tergantung koneksi serta perangkatmu, mudah memakan sepuluh sampai tiga puluh menit. Setelah itu tersisa indeks sebesar beberapa ratus megabyte. Pada koneksi yang dibayar per megabyte, sebaiknya jangan lakukan ini.',
  'Er was te weinig schijfruimte. De opbouw vraagt tijdelijk ruim 1,5 GB.':
      'Ruang disk tidak mencukupi. Pembangunan indeks sementara membutuhkan lebih dari 1,5 GB.',
  'Het opgehaalde archief was niet wat we verwachtten en is geweigerd. Er is niets geïnstalleerd.':
      'Arsip yang diunduh bukan yang kami harapkan dan ditolak. Tidak ada yang dipasang.',
  'Indexeren…': 'Mengindeks…',
  'Lokaal beschikbaar — opzoeken gebeurt offline, er gaat geen zoekterm naar buiten.':
      'Tersedia secara lokal — pencarian berlangsung offline, tidak ada kata kunci yang keluar.',
  'Lokale CVE-database': 'Basis data CVE lokal',
  'Met de CVE-lijst op je eigen apparaat blijft het opzoeken hier: er gaat geen zoekterm meer naar een server, en niemand kan zien welk lek je onderzoekt.':
      'Dengan daftar CVE di perangkatmu sendiri, pencarian tetap di sini: tidak ada lagi kata kunci yang dikirim ke server, dan tidak ada yang bisa melihat celah keamanan mana yang kamu teliti.',
  'Uitpakken…': 'Mengekstrak…',
  'Zet de volledige CVE-lijst op dit apparaat, zodat opzoeken offline gebeurt en je zoekterm nergens heen gaat. De database komt van CVE List V5 (het officiële CVE-programma, via GitHub).':
      'Tempatkan daftar CVE lengkap di perangkat ini, agar pencarian berlangsung offline dan kata kuncimu tidak pergi ke mana-mana. Basis data ini berasal dari CVE List V5 (program CVE resmi, melalui GitHub).',
  'Wat er lokaal beschikbaar is': 'Yang tersedia secara lokal',
  'Nu bijwerken': 'Perbarui sekarang',
  'Gegevens lokaal beschikbaar — het opzoeken gebeurt op dit apparaat, er gaat niets naar buiten.':
      'Data tersedia secara lokal — pencarian dilakukan di perangkat ini; tidak ada yang keluar.',
  'Zwakheden (CWE)': 'Kelemahan (CWE)',
  'Testgevallen (WSTG)': 'Kasus uji (WSTG)',
  'MIAUW-eisen': 'Persyaratan MIAUW',
  'CVSS-scoretabel': 'Tabel skor CVSS',
  'Bevindingsjablonen': 'Templat temuan',
  'Zoek een instelling': 'Cari pengaturan',
  'Geen instelling gevonden': 'Pengaturan tidak ditemukan',
  'Je zoekterm gaat naar de ingestelde CVE-mirror, en als die niets vindt ook naar ENISA en MITRE. Wie die servers beheert, kan daaruit afleiden naar welk specifiek lek je zoekt — en dus welk lek je onderzoekt.':
      'Kata pencarian Anda dikirim ke mirror CVE yang dikonfigurasi, dan jika tidak menemukan apa pun, juga ke ENISA dan MITRE. Pengelola server tersebut dapat menyimpulkan kerentanan spesifik mana yang Anda cari — dan dengan demikian kerentanan mana yang sedang Anda selidiki.',
  'Accepteren': 'Terima',
  'Accepteren + waarschuwen': 'Terima + peringatkan',
  'Accepteren: de gegevens horen hier en de melding verdwijnt. Accepteren + waarschuwen: de ontvanger ziet een badge dat er persoonsgegevens op de slide staan. Weglaten: de gevonden gegevens worden onleesbaar gemaakt op het scherm en in de export — je markdown-bestand houdt de oorspronkelijke tekst.':
      'Terima: datanya memang milik sini dan pemberitahuan hilang. Terima + peringatkan: penerima melihat lencana bahwa slide memuat data pribadi. Hilangkan: data yang ditemukan dibuat tak terbaca di layar dan di ekspor — berkas Markdown Anda tetap menyimpan teks aslinya.',
  'Alleen melden': 'Hanya laporkan',
  'PERSOONSGEGEVENS': 'DATA PRIBADI',
  'Volg de presentatie': 'Ikuti presentasi',
  'Weglaten uit tonen en exporteren': 'Hilangkan dari tampilan dan ekspor',
  ' Overweeg dit te redigeren met [[dubbele blokhaken]].':
      ' Pertimbangkan untuk meredaksinya dengan [[kurung siku ganda]].',
  ' Zonder context in de tekst is dit mogelijk geen persoonsgegeven.':
      ' Tanpa konteks dalam teks, ini mungkin bukan data pribadi.',
  'Leest je dia\'s na op identificatienummers, contactgegevens en andere privacygevoelige gegevens, en meldt ze bij de kwaliteitscontrole. Dit gebeurt volledig op dit apparaat; er wordt niets verstuurd. Het is een hulpmiddel, geen garantie: tekst in afbeeldingen en gegevens zonder herkenbaar patroon blijven buiten beeld.':
      'Memeriksa slide Anda untuk nomor identifikasi, data kontak, dan data sensitif privasi lainnya, lalu melaporkannya di pemeriksaan kualitas. Ini terjadi sepenuhnya di perangkat ini; tidak ada yang dikirim. Ini alat bantu, bukan jaminan: teks di dalam gambar dan data tanpa pola yang dikenali tetap tidak terlihat.',
  'Mogelijk persoonsgegeven': 'Kemungkinan data pribadi',
  'Privacycontrole': 'Pemeriksaan privasi',
  'Waarschuw bij mogelijke persoonsgegevens':
      'Peringatkan tentang kemungkinan data pribadi',
  'burgerservicenummer (BSN)': 'nomor layanan warga (BSN)',
  'bankrekeningnummer (IBAN)': 'nomor rekening bank (IBAN)',
  'e-mailadres': 'alamat email',
  'De TSA-handtekening is niet in-app geverifieerd; alleen de hash komt overeen.':
      'Tanda tangan TSA tidak diverifikasi di dalam aplikasi; hanya hash yang cocok.',
  'Extern': 'Eksternal',
  'Van een externe URL opgehaald; het openen heeft die server benaderd.':
      'Diambil dari URL eksternal; membukanya menghubungi server itu.',
  'AI-assistentie (staat standaard uit): kies je een zelf-gehoste of cloud-backend, dan worden de teksten of afbeeldingen die je laat verwerken naar dat adres gestuurd. Wat je hebt geredigeerd, gaat er eerst uit. Een lokaal AI-model op dit apparaat verstuurt niets.':
      'Bantuan AI (mati secara bawaan): jika Anda memilih backend swakelola atau awan, teks atau gambar yang Anda proses dikirim ke alamat tersebut. Apa pun yang Anda redaksi dihapus lebih dulu. Model AI lokal di perangkat ini tidak mengirim apa pun.',
  'Gegevens weglaten (redactie)': 'Menghilangkan data (redaksi)',
  'Zet je tekst tussen dubbele blokhaken, zoals [[het adres]], dan laat OciDeck die weg uit alles wat je toont en exporteert. Op de dia, in de presentatie, in de PDF, de PowerPoint en de HTML verschijnen alleen blokken.':
      'Letakkan teks di antara kurung siku ganda, seperti [[alamatnya]], maka OciDeck menghilangkannya dari semua yang Anda tampilkan dan ekspor. Pada slide, dalam presentasi, di PDF, PowerPoint, dan HTML hanya muncul blok.',
  'Weggelaten is écht weggelaten, niet afgedekt. De tekst zit niet als onzichtbare laag onder een zwart balkje in de PDF, niet in de sprekersnotities van de PowerPoint, en niet in de broncode van de HTML. Wie het bestand openmaakt, kan er niets uit terughalen.':
      'Dihilangkan berarti benar-benar dihilangkan, bukan ditutupi. Teksnya tidak tersimpan sebagai lapisan tak terlihat di bawah bilah hitam dalam PDF, tidak di catatan pembicara PowerPoint, dan tidak di kode sumber HTML. Siapa pun yang membuka berkasnya tidak bisa mengambil apa pun.',
  'Je eigen bestand verandert niet. De oorspronkelijke tekst blijft in je markdown staan; redactie geldt alleen voor wat je deelt. Zo houd je je eigen gegevens.':
      'Berkas Anda sendiri tidak berubah. Teks aslinya tetap ada di markdown Anda; redaksi hanya berlaku untuk yang Anda bagikan. Dengan begitu data Anda tetap milik Anda.',
